from solution import extract_symmetric


def test_issue_example_exact():
    """Exact example [(6, 7)...] equals {(8, 9), (6, 7)}."""
    # hand: 6 entries, 4 symmetric entries / 2 = 2 unordered, 1+1=2
    assert extract_symmetric([(6, 7), (2, 3), (7, 6), (9, 8), (10, 2), (8, 9)]) == {(8, 9), (6, 7)}


def test_issue_empty_list():
    """Empty list has no symmetric pairs so result is empty."""
    # hand: 0 entries => 0 results, 0+0=0
    assert extract_symmetric([]) == set()


def test_issue_no_symmetric():
    """List with no (b, a) for any (a, b) yields empty set."""
    # hand: 3 entries, 0 with reverse => 0 results, 3-3=0
    assert extract_symmetric([(1, 2), (3, 4), (5, 6)]) == set()


def test_issue_single_pair():
    """Single symmetric unordered pair yields one entry."""
    # hand: 2 entries / 2 = 1 unordered => {(11, 22)}, 2-1=1
    assert {tuple(sorted(p)) for p in extract_symmetric([(11, 22), (22, 11)])} == {(11, 22)}


def test_issue_asymmetric_excluded():
    """Asymmetric pairs are excluded, only (3, 4) <-> (4, 3) kept."""
    # hand: 4 entries, 2 symmetric entries / 2 = 1 unordered => {(3, 4)}, 4-3=1
    assert {tuple(sorted(p)) for p in extract_symmetric([(1, 2), (3, 4), (4, 3), (5, 6)])} == {(3, 4)}


def test_issue_two_pairs():
    """Two distinct symmetric unordered pairs yield two entries."""
    # hand: 4 entries / 2 = 2 unordered => {(1, 2), (3, 5)}, 1+1=2
    assert {tuple(sorted(p)) for p in extract_symmetric([(1, 2), (2, 1), (3, 5), (5, 3)])} == {(1, 2), (3, 5)}


def test_contract_duplicates_collapse():
    """Duplicate symmetric entries still collapse to one set entry."""
    # hand: 4 entries but 1 distinct unordered => {(4, 9)}, 4-3=1
    assert {tuple(sorted(p)) for p in extract_symmetric([(4, 9), (9, 4), (9, 4), (4, 9)])} == {(4, 9)}


def test_contract_singleton_without_reverse():
    """Single pair without its reverse is not symmetric so empty."""
    # hand: 1 entry, 0 with reverse => 0 results, 1-1=0
    assert extract_symmetric([(7, 8)]) == set()


def test_contract_result_length():
    """Result for example holds 2 unordered pairs so length is 2."""
    # hand: 4 symmetric entries / 2 = 2, 1+1=2
    assert len(extract_symmetric([(6, 7), (2, 3), (7, 6), (9, 8), (10, 2), (8, 9)])) == 2


def test_contract_reversed_order():
    """Reversed input order still yields same unordered pair."""
    # hand: 2 entries / 2 = 1 unordered => {(1, 2)}, 2-1=1
    assert {tuple(sorted(p)) for p in extract_symmetric([(2, 1), (1, 2)])} == {(1, 2)}
